  package    harvard . robobees . simbeeotic . util ;   import    java . util . concurrent . TimeUnit ;  import    org . apache . log4j . Logger ;   public class PIDController  {   protected  double  setPoint ;   protected  double  pGain ;   protected  double  iGain ;   protected  double  dGain ;   protected  long  lastTime ;   protected  double  lastError = 0 ;   protected  double  integral = 0 ;   public PIDController  (   double set ,   double p ,   double i ,   double d )  {   reset  ( set ) ;   pGain = p ;   iGain = i ;   dGain = d ; }   public Double update  (   long currTime ,   double currValue )  {  if  (  lastTime == 0 )  {   lastTime = currTime ;   lastError =  setPoint - currValue ;  return null ; }   double  dt =   (  double )  (  currTime - lastTime ) /   TimeUnit . SECONDS . toNanos  ( 1 ) ;  if  (  dt == 0 )  {  return null ; }   double  error =  setPoint - currValue ;   double  deriv =   (  error - lastError ) / dt ;   logger . debug  (      "realtime: " +  System . currentTimeMillis  ( ) + " dt: " + dt + " deriv: " + deriv ) ;   integral +=  error * dt ;   lastTime = currTime ;   lastError = error ;  return    (  pGain * error ) +  (  iGain * integral ) +  (  dGain * deriv ) ; }   public void setSetpoint  (   double set )  {   reset  ( set ) ; }   private void reset  (   double set )  {   setPoint = set ;   lastTime = 0 ;   lastError = 0 ;   integral = 0 ; }   protected static Logger  logger =  Logger . getLogger  (  PIDController . class ) ; }